#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────
#
# Glacial Lake Monitor: paste AWS keys for both accounts, everything else is automatic.
#   cd infra && ./setup.sh               (keys asked once, then reused)
#   cd infra && ./setup.sh --new-keys    (replace the saved keys)
# Secrets (access keys) go ONLY to ~/.aws/credentials via `aws configure`.
# Non-secret answers are remembered in infra/.setup.env (gitignored) for re-runs.

HERE="$(cd "$(dirname "$0")" && pwd)"
ENV_FILE="$HERE/.setup.env"
# Keys are asked for only once: later runs reuse the saved `main` / `sms` profiles
# when they still authenticate. Pass --new-keys to replace them.
NEW_KEYS=false
[[ "${1:-}" == "--new-keys" ]] && NEW_KEYS=true
TFVARS="$HERE/terraform/terraform.tfvars"
TOTAL_STAGES=8

for tool in aws terraform docker npm; do
  command -v "$tool" >/dev/null 2>&1 || { echo "Missing required tool: $tool"; exit 1; }
done

banner "Glacial Lake Monitor: deploy to AWS (two accounts)"

# helper: store keys in a named profile and return the account id (fails loudly)
configure_profile() { # profile key_id secret region
  aws configure set aws_access_key_id "$2" --profile "$1"
  aws configure set aws_secret_access_key "$3" --profile "$1"
  aws configure set region "$4" --profile "$1"
  aws configure set output json --profile "$1"
}
whoami_arn() { aws sts get-caller-identity --profile "$1" --query Arn --output text 2>/dev/null; }

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Main account: access key"
if [[ "$NEW_KEYS" == false ]] && MAIN_ARN="$(whoami_arn main)"; then
  say "Using the saved 'main' profile from ~/.aws/credentials (run ./setup.sh --new-keys to replace it)."
  MAIN_REGION="$(aws configure get region --profile main || true)"
  MAIN_REGION="${MAIN_REGION:-ap-south-1}"
  REUSED_MAIN=true
else
  say "The main account runs everything except SMS: website, API, Lambda, storage."
  say "Use an IAM user with admin rights, not the root user."
  open_url "https://console.aws.amazon.com/iam/home#/security_credentials"
  step "IAM -> Users -> your user -> Security credentials -> Create access key (CLI)."
  step "Copy the Access key ID and the Secret access key."
  ask MAIN_KEY_ID "Main account Access key ID:"
  ask_secret MAIN_SECRET "Main account Secret access key (hidden):"
  ask MAIN_REGION "Main region [ap-south-1]:"
  MAIN_REGION="${MAIN_REGION:-ap-south-1}"
  [[ -n "$MAIN_KEY_ID" && -n "$MAIN_SECRET" ]] || { warn "both values are required"; exit 1; }
  configure_profile main "$MAIN_KEY_ID" "$MAIN_SECRET" "$MAIN_REGION"
  unset MAIN_SECRET
  MAIN_ARN="$(whoami_arn main)" || { warn "these keys do not authenticate; check them and re-run"; exit 1; }
  write_env MAIN_KEY_ID "$MAIN_KEY_ID"
  REUSED_MAIN=false
fi
MAIN_ID="$(aws sts get-caller-identity --profile main --query Account --output text)"
printf '  %s✓ main account %s%s (%s)\n' "$GREEN" "$MAIN_ID" "$RESET" "$MAIN_ARN"
if [[ "$MAIN_ARN" == *":root" ]]; then
  warn "These are ROOT keys. Create an IAM user instead if you can."
  confirm "Continue with root keys anyway?" || exit 1
fi
write_env MAIN_REGION "$MAIN_REGION"
[[ "$REUSED_MAIN" == true ]] || pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "SMS account: access key"
if [[ "$NEW_KEYS" == false ]] && SMS_ARN="$(whoami_arn sms)"; then
  say "Using the saved 'sms' profile from ~/.aws/credentials (run ./setup.sh --new-keys to replace it)."
  REUSED_SMS=true
else
  say "The SMS account only holds the SNS topic (us-east-1, where your phones are verified)."
  say "Best: an IAM user there with only SNS permissions (sns:* and sts:GetCallerIdentity)."
  open_url "https://console.aws.amazon.com/iam/home#/security_credentials"
  step "Sign in to the SMS account, create an access key for that user, copy both values."
  ask SMS_KEY_ID "SMS account Access key ID:"
  ask_secret SMS_SECRET "SMS account Secret access key (hidden):"
  [[ -n "$SMS_KEY_ID" && -n "$SMS_SECRET" ]] || { warn "both values are required"; exit 1; }
  configure_profile sms "$SMS_KEY_ID" "$SMS_SECRET" "us-east-1"
  unset SMS_SECRET
  SMS_ARN="$(whoami_arn sms)" || { warn "these keys do not authenticate; check them and re-run"; exit 1; }
  write_env SMS_KEY_ID "$SMS_KEY_ID"
  REUSED_SMS=false
fi
SMS_ID="$(aws sts get-caller-identity --profile sms --query Account --output text)"
printf '  %s✓ SMS account %s%s (%s)\n' "$GREEN" "$SMS_ID" "$RESET" "$SMS_ARN"
[[ "$SMS_ID" != "$MAIN_ID" ]] || { warn "Both keys belong to account $MAIN_ID. The SMS keys must be from the other account."; exit 1; }
[[ "$SMS_ARN" == *":root" ]] && warn "ROOT keys for the SMS account. An SNS-only IAM user is safer."
[[ "$REUSED_SMS" == true ]] || pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Phone numbers"
say "Reading the numbers already verified in the SMS sandbox (SMS account, us-east-1)..."
VERIFIED="$(aws sns list-sms-sandbox-phone-numbers --region us-east-1 --profile sms \
  --query "PhoneNumbers[?Status=='Verified'].PhoneNumber" --output text 2>/dev/null | tr '\t' ' ' || true)"
if [[ -z "${VERIFIED// /}" ]]; then
  warn "No verified numbers found (or the SMS user lacks sns permissions)."
  open_url "https://us-east-1.console.aws.amazon.com/sns/v3/home?region=us-east-1#/mobile/text-messaging"
  step "Text messaging (SMS) -> Sandbox destination phone numbers -> Add and verify each phone."
  pause "Press Enter once they show as Verified, then re-run ./setup.sh"
  exit 1
fi
for n in $VERIFIED; do note "verified: ...${n: -4}"; done
if confirm "Send the drill SMS to all $(wc -w <<<"$VERIFIED" | tr -d ' ') verified number(s)?"; then
  NUMBERS="$VERIFIED"
else
  ask NUMBERS "Numbers to use, space separated, E.164 (e.g. +91XXXXXXXXXX):"
  for n in $NUMBERS; do grep -qw -- "$n" <<<"$VERIFIED" || { warn "...${n: -4} is not verified"; exit 1; }; done
fi
write_env NUMBERS "$NUMBERS"
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Email alerts"
say "Every address gets the alerts by email. Each must click a confirmation link after deploy."
ask EMAILS "Email address(es), space separated (Enter for none):"
write_env EMAILS "$EMAILS"
ask SPEND "Monthly SMS spend cap in USD [1]:"
SPEND="${SPEND:-1}"
write_env SPEND "$SPEND"
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Real SMS drill"
say "Off: the site works, alerts are practice only. On: when the History replay reaches"
say "Warning (Oct 2023), ONE real drill SMS goes to the phones above, automatically, once per run."
warn "While on, anyone pressing Play on the public site can trigger it (5-minute cooldown, spend cap)."
if confirm "Turn the real SMS drill ON for this deploy?"; then DRILL=true; else DRILL=false; fi
write_env DRILL "$DRILL"
[[ "$DRILL" == true ]] && DRY=false || DRY=true
say ""
say "CloudFront gives the site HTTPS, but brand-new AWS accounts are often blocked from"
say "creating it until AWS Support verifies the account."
if confirm "Has AWS verified this account for CloudFront? (No = serve over HTTP from the load balancer)"; then
  CDN=true; else CDN=false; fi
write_env CDN "$CDN"
hcl_list() { local out="" x; for x in $1; do out+="\"$x\", "; done; printf '[%s]' "${out%, }"; }
cat > "$TFVARS" <<HCL
# Written by infra/setup.sh (gitignored). Re-run setup.sh to change.
main_profile             = "main"
sms_profile              = "sms"
main_region              = "$MAIN_REGION"
expected_main_account_id = "$MAIN_ID"
expected_sms_account_id  = "$SMS_ID"
demo_sms_numbers         = $(hcl_list "$NUMBERS")
alert_emails             = $(hcl_list "$EMAILS")
sms_spend_limit          = $SPEND
alert_dry_run            = $DRY
sim_live_sms             = $DRILL
demo_sms_live            = $DRILL
enable_cloudfront        = $CDN
HCL
printf '  %s✓ wrote%s terraform/terraform.tfvars\n' "$GREEN" "$RESET"
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Terraform state bucket"
say "One private, versioned bucket in the main account holds Terraform's state."
"$HERE/bootstrap-state.sh" main "$MAIN_REGION"
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Docker"
if ! docker info >/dev/null 2>&1; then
  say "Docker is needed to build the two container images. Starting it..."
  (open -a Docker 2>/dev/null || systemctl --user start docker 2>/dev/null) || true
  for _ in $(seq 1 60); do docker info >/dev/null 2>&1 && break; sleep 3; done
fi
docker info >/dev/null 2>&1 || { warn "Docker is still not running. Start Docker Desktop, then re-run ./setup.sh"; exit 1; }
printf '  %s✓ Docker is running%s\n' "$GREEN" "$RESET"
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Deploy"
say "This creates billable resources in both accounts (CloudFront, an ALB, one Fargate"
say "task, Lambda, S3, DynamoDB, SNS). Tear down later with ./destroy.sh."
say "First run takes 15-25 minutes (image builds + CloudFront)."
confirm "Deploy now?" || { warn "Stopped before deploying. Run ./deploy.sh when ready."; exit 0; }
"$HERE/deploy.sh"

KEY_SECRET="$(terraform -chdir="$HERE/terraform" output -raw api_key_secret 2>/dev/null || echo glof/alert-api-key)"
OPKEY="$(aws secretsmanager get-secret-value --secret-id "$KEY_SECRET" --query SecretString --output text \
  --profile main --region "$MAIN_REGION" 2>/dev/null || true)"
SITE="$(terraform -chdir="$HERE/terraform" output -raw site_url 2>/dev/null || true)"

finish
say "Site:          ${SITE:-see deploy output}"
[[ -n "$OPKEY" ]] && say "Operator key:  $OPKEY   (needed for Send test, Re-arm and Approve)"
say ""
say "Left to do by hand:"
step "Open each inbox and click the AWS SNS 'Confirm subscription' link (expires in 3 days)."
if [[ "$DRILL" == true ]]; then
  step "Open the site, press Play in History: at Warning (Oct 2023) the phones get one SMS."
  step "Optional first: Flood night -> paste the operator key -> Send test."
else
  step "Drill is OFF. To enable it later: ./setup.sh again and answer yes at stage 5."
fi
printf '\n'
